CREATE TABLE IF NOT EXISTS library_likutey_halajot_note_source_units_v1 (
 id UUID PRIMARY KEY DEFAULT gen_random_uuid(), document_id UUID NOT NULL REFERENCES library_documents(id), pdf_page INTEGER NOT NULL, page_anchor_id UUID NOT NULL REFERENCES library_page_anchors_v2(page_anchor_id), parent_fine_zone_id UUID REFERENCES library_likutey_halajot_fine_zones_v1(id), note_source_run_id TEXT NOT NULL, unit_type TEXT NOT NULL, unit_role TEXT NOT NULL, visible_note_number TEXT, marker_value TEXT, source_or_commentator TEXT, text_quote TEXT NOT NULL, char_start INTEGER NOT NULL, char_end INTEGER NOT NULL, quote_hash TEXT NOT NULL, confidence NUMERIC NOT NULL, validation_status TEXT NOT NULL, review_status TEXT NOT NULL, halakhah_header_hint TEXT, warnings JSONB NOT NULL DEFAULT '[]'::jsonb, raw_detection JSONB NOT NULL DEFAULT '{}'::jsonb, UNIQUE(note_source_run_id,parent_fine_zone_id,unit_type,char_start,char_end));
CREATE OR REPLACE VIEW library_likutey_halajot_note_source_search_v1 AS
SELECT n.pdf_page,a.printed_page_number AS printed_page,n.halakhah_header_hint,n.unit_type,n.unit_role,n.visible_note_number,n.marker_value,n.source_or_commentator,n.text_quote,n.confidence,n.validation_status,n.review_status,n.warnings FROM library_likutey_halajot_note_source_units_v1 n JOIN library_page_anchors_v2 a ON a.page_anchor_id=n.page_anchor_id;
